it('unique options, default A, select enabled', () => {
  const sel = container.querySelector('select[data-part=root]');
  expect(sel).toBeTruthy(); expect(sel.disabled).toBe(false);
  expect(sel.value).toBe('a');
  const bCount = Array.from(sel.options).filter(o => o.value === 'b').length;
  expect(bCount).toBe(1);
});
it('select change fires', () => {
  const sel = container.querySelector('select[data-part=root]');
  let changed = null; sel.addEventListener('change', () => { changed = sel.value; });
  sel.value = 'b'; sel.dispatchEvent(new Event('change', { bubbles: true }));
  expect(changed).toBe('b');
});
